    sumval = dpct::select_from_sub_group(
        sycl::ext::oneapi::this_work_item::get_sub_group(), sumval, 0);

    for (int i = laneId; i < C;
         i += sycl::ext::oneapi::this_work_item::get_sub_group()
                  .get_local_range()
                  .get(0)) {
        y[i] = sycl::native::exp(x[i] - maxval) / sumval;
    }
