  }
  fclose(fin);
  for (int k = 0; k < 3; ++k)
    for (int j = 0; j < B * T; ++j)
      inp[(size_t)j * V + outliers[(size_t)j * 3 + k]] *= 20;
  free(outliers);

  sycl::queue q;
  float *d_inp = sycl::malloc_device<float>(NV, q);
