      break;
    case 6:
      run_k6(q, d_out, d_inp, (int)N, (int)C, 256);
      break;
    case 7:
      run_k7(q, d_out, d_inp, (int)N, (int)C, 256);
      break;
    case 8:
      run_k8(q, d_out, d_inp, (int)N, (int)C, 256);
      break;
    }
    q.wait();
    q.memcpy(out, d_out, sizeof(float) * NV).wait();
    fwrite(out, sizeof(float), NV, fout);
  }
  fclose(fout);
