          float inv = (float)(1.0 / sum);
          for (int j = 0; j < C; ++j)
            row_out[j] = sycl::exp(row_in[j] - maxval) * inv;
        }
      });
}

// ---- variant 6: online, one sub-group per row with SumMax reduction ----
class SoftmaxK6;
