#pragma unroll
            for (int u = 0; u < UNROLL; ++u) {
              int j = i + u * bl;
              if (j < C) {
                float o = sycl::exp(regs[u] - offset);
                int wj = j;
                if (wj >= C)
                  wj = C - 1;
                y[wj] = o;
                sumval += o;
              }
            }
          }
          float sgsum =
              sycl::reduce_over_group(sg, sumval, sycl::plus<float>());
          if (lane == 0)
            sumvals[sgid] = sgsum;
          it.barrier(sycl::access::fence_space::local_space);
          if (tid == 0) {
            float v = sumvals[0];
            for (int i = 1; i < nsg; ++i)
              v += sumvals[i];
            sumvals[0] = v;
          }
          it.barrier(sycl::access::fence_space::local_space);
          float sum = sumvals[0];
          for (int i = tid; i < C; i += bl * UNROLL) {
