        total.maxval = sycl::select_from_group(sg, total.maxval, 0);
        total.sum = sycl::select_from_group(sg, total.sum, 0);
        for (int i = lane; i < C; i += ssize)
          out[(size_t)idx * C + i] =
              sycl::exp(x[i] - total.maxval) / total.sum;
